--
-- Table structure for table `jurnal_life_checks`
--

DROP TABLE IF EXISTS `jurnal_life_checks`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `jurnal_life_checks` (
  `student_id` bigint unsigned NOT NULL,
  `life_item_id` bigint unsigned NOT NULL,
  `tanggal` date NOT NULL,
  `checked` tinyint(1) NOT NULL DEFAULT '1',
  `value` smallint unsigned DEFAULT NULL COMMENT 'Nilai numerik untuk item response_type=number (e.g. jumlah salah ayat)',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`student_id`,`life_item_id`,`tanggal`),
  KEY `jurnal_life_checks_life_item_id_foreign` (`life_item_id`),
  KEY `jurnal_life_checks_student_id_tanggal_index` (`student_id`,`tanggal`),
  CONSTRAINT `jurnal_life_checks_life_item_id_foreign` FOREIGN KEY (`life_item_id`) REFERENCES `jurnal_life_items` (`id`) ON DELETE CASCADE,
  CONSTRAINT `jurnal_life_checks_student_id_foreign` FOREIGN KEY (`student_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

