--
-- Table structure for table `jurnal_life_items`
--

DROP TABLE IF EXISTS `jurnal_life_items`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `jurnal_life_items` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `kategori` enum('kerohanian','pendidikan','karakter','pembacaan','sidang','rohani','prajurit') COLLATE utf8mb4_unicode_ci NOT NULL,
  `response_type` enum('check','boolean','time_range','number') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'check',
  `reset_period` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'daily',
  `label` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `is_default` tinyint(1) NOT NULL DEFAULT '0',
  `student_id` bigint unsigned DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `created_by` bigint unsigned DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `jurnal_life_items_created_by_foreign` (`created_by`),
  KEY `jurnal_life_items_kategori_is_active_index` (`kategori`,`is_active`),
  KEY `jurnal_life_items_student_id_index` (`student_id`),
  CONSTRAINT `jurnal_life_items_created_by_foreign` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `jurnal_life_items_student_id_foreign` FOREIGN KEY (`student_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=29 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

