INSERT INTO `nametag_templates` VALUES (1,'standard','Standard','Teks nama, kelas, sekolah. Tanpa foto.',8.5,5.5,'portrait','<div class=\"nametag\" style=\"width:{width}cm;height:{height}cm\">\n    <div class=\"corner-tr\">\n        <img src=\"{corner_tr_url}\" style=\"width:100%;height:100%;display:block\" alt=\"\">\n    </div>\n    <div class=\"corner-bl\">\n        <img src=\"{corner_bl_url}\" style=\"width:100%;height:100%;display:block\" alt=\"\">\n    </div>\n\n    <div class=\"head\">\n        <img src=\"{logo_url}\" alt=\"Logo\" class=\"logo\" onerror=\"this.style.display=\'none\'\">\n        <div class=\"titles\">\n            <div class=\"title-main\">STUDY CENTER</div>\n            <div class=\"title-sub\">STUDY CENTER KABUPATEN NIAS</div>\n            <div class=\"title-tag\">SECOND HOME FOR THE BETTER FUTURE</div>\n        </div>\n    </div>\n    <div class=\"divider\"></div>\n\n    <div class=\"body\">\n        <div class=\"row-line\">\n            <span class=\"label\">Nama</span><span class=\"colon\">:</span>\n            <span class=\"value\">{name}</span>\n        </div>\n        <div class=\"row-line\">\n            <span class=\"label\">Kelas</span><span class=\"colon\">:</span>\n            <span class=\"value\">{kelas}</span>\n        </div>\n        <div class=\"row-line\">\n            <span class=\"label\">Sekolah</span><span class=\"colon\">:</span>\n            <span class=\"value\">{sekolah}</span>\n        </div>\n    </div>\n    <div style=\"position:absolute;bottom:3mm;right:3mm;z-index:2;width:14mm;height:14mm;overflow:hidden\">\n        {qr_html}\n    </div>\n</div>',1,'2026-08-30 10:19:05','2026-08-30 10:19:05'),(2,'with_photo','Dengan Foto','Foto profil siswa (3:4) di kiri, info di kanan.',9.0,6.0,'portrait','<div class=\"nametag nametag-photo\" style=\"width:{width}cm;height:{height}cm\">\n    <div class=\"corner-tr\">\n        <img src=\"{corner_tr_url}\" style=\"width:100%;height:100%;display:block\" alt=\"\">\n    </div>\n    <div class=\"corner-bl\">\n        <img src=\"{corner_bl_url}\" style=\"width:100%;height:100%;display:block\" alt=\"\">\n    </div>\n\n    <div class=\"head\">\n        <img src=\"{logo_url}\" alt=\"Logo\" class=\"logo\" onerror=\"this.style.display=\'none\'\">\n        <div class=\"titles\">\n            <div class=\"title-main\">STUDY CENTER</div>\n            <div class=\"title-sub\">STUDY CENTER KABUPATEN NIAS</div>\n            <div class=\"title-tag\">SECOND HOME FOR THE BETTER FUTURE</div>\n        </div>\n    </div>\n    <div class=\"divider\"></div>\n\n    <div class=\"photo-body\">\n        <div class=\"photo-box\">\n            {photo_html}\n        </div>\n        <div class=\"info-col\">\n            <div class=\"info-name\">{name}</div>\n            <div class=\"info-row\">\n                <span class=\"info-label\">Kelas</span>\n                <span class=\"info-sep\">:</span>\n                <span class=\"info-val\">{kelas}</span>\n            </div>\n            <div class=\"info-row\">\n                <span class=\"info-label\">Sekolah</span>\n                <span class=\"info-sep\">:</span>\n                <span class=\"info-val\">{sekolah}</span>\n            </div>\n            <div class=\"info-row\">\n                <span class=\"info-label\">Cabang</span>\n                <span class=\"info-sep\">:</span>\n                <span class=\"info-val\">{cabang}</span>\n            </div>\n            <div style=\"margin-top:2mm;width:12mm;height:12mm;overflow:hidden\">\n                {qr_html}\n            </div>\n        </div>\n    </div>\n</div>',1,'2026-08-30 10:19:05','2026-08-30 10:19:05'),(3,'landscape','Landscape','Orientasi horizontal dengan foto dan info.',9.0,5.5,'landscape','<div class=\"nametag nametag-landscape\" style=\"width:{width}cm;height:{height}cm\">\n    <div class=\"corner-tr\">\n        <img src=\"{corner_tr_url}\" style=\"width:100%;height:100%;display:block\" alt=\"\">\n    </div>\n    <div class=\"corner-bl\">\n        <img src=\"{corner_bl_url}\" style=\"width:100%;height:100%;display:block\" alt=\"\">\n    </div>\n\n    <div class=\"ls-photo\">\n        {photo_html}\n    </div>\n\n    <div class=\"ls-content\">\n        <div class=\"ls-header\">\n            <img src=\"{logo_url}\" alt=\"Logo\" class=\"logo-sm\" onerror=\"this.style.display=\'none\'\">\n            <div class=\"ls-brand\">\n                <div class=\"ls-title\">STUDY CENTER</div>\n                <div class=\"ls-sub\">KABUPATEN NIAS</div>\n            </div>\n        </div>\n        <div class=\"ls-divider\"></div>\n        <div class=\"ls-name\">{name}</div>\n        <div class=\"ls-meta\">\n            <span class=\"ls-badge\">{kelas}</span>\n            <span class=\"ls-badge\">{sekolah}</span>\n            <span class=\"ls-badge ls-badge-cabang\">{cabang}</span>\n        </div>\n    </div>\n    <div style=\"flex-shrink:0;width:14mm;height:14mm;overflow:hidden;align-self:center;margin-left:2mm\">\n        {qr_html}\n    </div>\n</div>',1,'2026-08-30 10:19:05','2026-08-30 10:19:05'),(4,'portrait_large','Portrait Besar (Foto + QR)','Potrait 8.5×11cm dengan foto besar dan QR code.',8.5,11.0,'portrait','<div class=\"nametag nametag-lg\" style=\"width:{width}cm;height:{height}cm\">\n    <div class=\"corner-tr\">\n        <img src=\"{corner_tr_url}\" style=\"width:100%;height:100%;display:block\" alt=\"\">\n    </div>\n    <div class=\"corner-bl\">\n        <img src=\"{corner_bl_url}\" style=\"width:100%;height:100%;display:block\" alt=\"\">\n    </div>\n\n    <div class=\"head\">\n        <img src=\"{logo_url}\" alt=\"Logo\" class=\"logo\" onerror=\"this.style.display=\'none\'\">\n        <div class=\"titles\">\n            <div class=\"title-main\">STUDY CENTER</div>\n            <div class=\"title-sub\">STUDY CENTER KABUPATEN NIAS</div>\n            <div class=\"title-tag\">SECOND HOME FOR THE BETTER FUTURE</div>\n        </div>\n    </div>\n    <div class=\"divider\"></div>\n\n    <div class=\"lg-photo-wrap\">\n        <div class=\"lg-photo-box\">\n            {photo_html}\n        </div>\n    </div>\n\n    <div class=\"lg-info\">\n        <div class=\"lg-name\">{name}</div>\n        <div class=\"lg-rows\">\n            <div class=\"lg-row\">\n                <span class=\"lg-label\">Kelas</span>\n                <span class=\"lg-colon\">:</span>\n                <span class=\"lg-val\">{kelas}</span>\n            </div>\n            <div class=\"lg-row\">\n                <span class=\"lg-label\">Sekolah</span>\n                <span class=\"lg-colon\">:</span>\n                <span class=\"lg-val\">{sekolah}</span>\n            </div>\n            <div class=\"lg-row\">\n                <span class=\"lg-label\">Cabang</span>\n                <span class=\"lg-colon\">:</span>\n                <span class=\"lg-val\">{cabang}</span>\n            </div>\n        </div>\n    </div>\n\n    <div class=\"lg-footer\">\n        <div class=\"lg-qr\">{qr_html}</div>\n    </div>\n</div>',1,'2026-08-30 10:19:05','2026-08-30 10:19:05');
